import os
import time
import json
import urllib.request
import urllib.error
from abc import ABC, abstractmethod
from typing import List, Dict, Any, Optional

# --- Core HTTP Transport with Retry Backoff (urllib-based) ---
class RetryableHTTPClient:
    """
    A simple HTTP client using urllib with exponential backoff and retries.
    Adheres to the directive for standard urllib HTTP transport.
    """
    def __init__(self, max_retries: int = 3, initial_backoff: float = 0.5):
        self.max_retries = max_retries
        self.initial_backoff = initial_backoff

    def _make_request(self, url: str, method: str, headers: Dict[str, str], data: Optional[bytes] = None) -> Dict[str, Any]:
        req = urllib.request.Request(url, data=data, headers=headers, method=method)

        for attempt in range(self.max_retries + 1):
            try:
                with urllib.request.urlopen(req, timeout=30) as response:
                    response_body = response.read().decode('utf-8')
                    return json.loads(response_body)
            except urllib.error.HTTPError as e:
                if e.code in [429, 500, 502, 503, 504] and attempt < self.max_retries:
                    wait_time = self.initial_backoff * (2 ** attempt)
                    print(f"HTTP Error {e.code} for {url}. Retrying in {wait_time:.2f}s (attempt {attempt + 1}/{self.max_retries})...")
                    time.sleep(wait_time)
                else:
                    print(f"HTTP Error {e.code} for {url}: {e.read().decode('utf-8')}")
                    raise
            except urllib.error.URLError as e:
                if attempt < self.max_retries:
                    wait_time = self.initial_backoff * (2 ** attempt)
                    print(f"URL Error for {url}: {e.reason}. Retrying in {wait_time:.2f}s (attempt {attempt + 1}/{self.max_retries})...")
                    time.sleep(wait_time)
                else:
                    print(f"URL Error for {url}: {e.reason}")
                    raise
            except Exception as e:
                print(f"An unexpected error occurred during request to {url}: {e}")
                raise
        raise RuntimeError(f"Failed to make request to {url} after {self.max_retries} retries.")

    def post(self, url: str, headers: Dict[str, str], json_data: Dict[str, Any]) -> Dict[str, Any]:
        data = json.dumps(json_data).encode('utf-8')
        headers['Content-Type'] = 'application/json'
        return self._make_request(url, "POST", headers, data)

    def get(self, url: str, headers: Dict[str, str]) -> Dict[str, Any]:
        return self._make_request(url, "GET", headers)

# --- LLM Provider Abstraction ---
class LLMProvider(ABC):
    """Abstract Base Class for all LLM providers."""

    @abstractmethod
    def chat_completion(self, messages: List[Dict[str, str]], model: str, **kwargs) -> str:
        """
        Generates a chat completion based on a list of messages.
        Messages format: [{"role": "user", "content": "Hello"}, ...]
        """
        pass

    @abstractmethod
    def get_available_models(self) -> List[str]:
        """Returns a list of models available through this provider."""
        pass

# --- Concrete LLM Provider Implementations ---

class OpenAIProvider(LLMProvider):
    """OpenAI API Provider."""
    def __init__(self):
        try:
            from openai import OpenAI
            self.client = OpenAI(api_key=os.getenv("OPENAI_API_KEY"))
        except ImportError:
            raise ImportError("Please install the 'openai' package to use OpenAIProvider.")
        except Exception as e:
            print(f"Warning: OpenAI client initialization failed. Check OPENAI_API_KEY. Error: {e}")
            self.client = None # Allow partial init for testing

    def chat_completion(self, messages: List[Dict[str, str]], model: str, **kwargs) -> str:
        if not self.client:
            raise RuntimeError("OpenAI client not initialized. Check API key.")
        try:
            response = self.client.chat.completions.create(
                model=model,
                messages=messages,
                **kwargs
            )
            return response.choices[0].message.content
        except Exception as e:
            raise RuntimeError(f"OpenAI API call failed: {e}")

    def get_available_models(self) -> List[str]:
        # In a real scenario, this would query the API. For simplicity, hardcode common ones.
        return ["gpt-4o", "gpt-4-turbo", "gpt-3.5-turbo"]

class AnthropicProvider(LLMProvider):
    """Anthropic API Provider."""
    def __init__(self):
        try:
            from anthropic import Anthropic
            self.client = Anthropic(api_key=os.getenv("ANTHROPIC_API_KEY"))
        except ImportError:
            raise ImportError("Please install the 'anthropic' package to use AnthropicProvider.")
        except Exception as e:
            print(f"Warning: Anthropic client initialization failed. Check ANTHROPIC_API_KEY. Error: {e}")
            self.client = None

    def chat_completion(self, messages: List[Dict[str, str]], model: str, **kwargs) -> str:
        if not self.client:
            raise RuntimeError("Anthropic client not initialized. Check API key.")
        # Anthropic API expects 'system' message separately if present
        system_message = ""
        filtered_messages = []
        for msg in messages:
            if msg["role"] == "system":
                system_message = msg["content"]
            else:
                filtered_messages.append(msg)

        try:
            response = self.client.messages.create(
                model=model,
                max_tokens=kwargs.pop("max_tokens", 1024), # Anthropic requires max_tokens
                messages=filtered_messages,
                system=system_message if system_message else None,
                **kwargs
            )
            return response.content[0].text
        except Exception as e:
            raise RuntimeError(f"Anthropic API call failed: {e}")

    def get_available_models(self) -> List[str]:
        return ["claude-3-opus-20240229", "claude-3-sonnet-20240229", "claude-3-haiku-20240307"]

class GeminiProvider(LLMProvider):
    """Google Gemini API Provider."""
    def __init__(self):
        try:
            import google.generativeai as genai
            api_key = os.getenv("GEMINI_API_KEY")
            if not api_key:
                raise ValueError("GEMINI_API_KEY environment variable not set.")
            genai.configure(api_key=api_key)
            self.client = genai
        except ImportError:
            raise ImportError("Please install the 'google-generativeai' package to use GeminiProvider.")
        except Exception as e:
            print(f"Warning: Gemini client initialization failed. Check GEMINI_API_KEY. Error: {e}")
            self.client = None

    def chat_completion(self, messages: List[Dict[str, str]], model: str, **kwargs) -> str:
        if not self.client:
            raise RuntimeError("Gemini client not initialized. Check API key.")

        # Gemini API expects messages in a specific format and role mapping
        # 'user' and 'model' roles are standard. 'system' role needs special handling.
        gemini_messages = []
        system_instruction = None
        for msg in messages:
            if msg["role"] == "system":
                system_instruction = msg["content"]
            elif msg["role"] == "assistant": # Map assistant to model for Gemini
                gemini_messages.append({"role": "model", "parts": [msg["content"]]})
            else:
                gemini_messages.append({"role": msg["role"], "parts": [msg["content"]]})

        try:
            model_instance = self.client.GenerativeModel(
                model_name=model,
                system_instruction=system_instruction
            )
            response = model_instance.generate_content(
                gemini_messages,
                **kwargs
            )
            return response.text
        except Exception as e:
            raise RuntimeError(f"Gemini API call failed: {e}")

    def get_available_models(self) -> List[str]:
        return ["gemini-pro", "gemini-1.5-pro-latest"]

class OllamaProvider(LLMProvider):
    """Ollama Local/Remote Provider using RetryableHTTPClient."""
    def __init__(self, base_url: str = "http://localhost:11434"):
        self.base_url = os.getenv("OLLAMA_BASE_URL", base_url)
        self.http_client = RetryableHTTPClient()

    def chat_completion(self, messages: List[Dict[str, str]], model: str, **kwargs) -> str:
        url = f"{self.base_url}/api/chat"
        payload = {
            "model": model,
            "messages": messages,
            "stream": False, # We want a single response
            **kwargs
        }
        try:
            response = self.http_client.post(url, {}, payload)
            return response["message"]["content"]
        except Exception as e:
            raise RuntimeError(f"Ollama API call failed: {e}")

    def get_available_models(self) -> List[str]:
        url = f"{self.base_url}/api/tags"
        try:
            response = self.http_client.get(url, {})
            return [m["name"] for m in response.get("models", [])]
        except Exception as e:
            print(f"Warning: Could not fetch Ollama models from {self.base_url}: {e}")
            return [] # Return empty list if Ollama is not running or accessible

# --- Provider Factory (Optional, for easier instantiation) ---
def get_llm_provider(provider_name: str) -> LLMProvider:
    """Factory function to get an LLM provider instance."""
    if provider_name.lower() == "openai":
        return OpenAIProvider()
    elif provider_name.lower() == "anthropic":
        return AnthropicProvider()
    elif provider_name.lower() == "gemini":
        return GeminiProvider()
    elif provider_name.lower() == "ollama":
        return OllamaProvider()
    else:
        raise ValueError(f"Unknown LLM provider: {provider_name}")
